Section CANSEC1. Context {rc : runConstT}.
Section W4E.
  Variable AI : AMallocIface.
  Notation CI := (aci AI).
  Variables (L : alayout) (RNG : footprint) (st : astate) (LB : list ablock).
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32) (m0 : amem).
  Variables (DST dcap SS DT mtl tl lo : Z) (src : list Z) (cells : list deltX1) (cbs : list byte) (pdt : aptr)
            (SBL SBH : Z) (rstk : region).
  Notation SP := (bv_unsigned sp).
  Notation SPF := (SP + -496).
  Notation n := (zlen src).
  Notation seg := ((dcap + 3) / 4).
  Notation DTL := (DTABLE_BYTES mtl).
  Hypothesis AH : AHEAP AI L RNG st LB m0.
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis TLM : tl <= mtl + 1.
  Hypothesis HDT : In (HB pdt DT DTL) LB.
  Hypothesis TOK : x1_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (2 * 2^tl)) (x1_bytes cells).
  Hypothesis LCB : zlen cbs = 2 * 2^tl.
  Hypothesis DSTF : (DST = 0 /\ dcap = 0) \/ (exists pb, In (HB pb DST dcap) LB).
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis NSM : n < 2^26.
  Hypothesis S16 : 16 <= SS.
  Hypothesis SRCB : 0 < n -> exists p, In (HB p SBL (SBH - SBL)) LB /\ SBL <= SS /\ SS + n <= SBH.
  (* [comment removed for export] *)
  Hypothesis DJ1 : KXGoM.apart DT DTL SS n.
  Hypothesis DJ2 : KXGoM.apart DST dcap SS n.
  Hypothesis DJ3 : KXGoM.apart DST dcap DT DTL.
  Hypothesis LOA : ATOP + 4096 <= lo.
  Hypothesis LOS : lo <= SP - HUF_DEC_STACK_A.
  Hypothesis SPT : SP + 16 < al_top L.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis RCL : rclean m0 rstk.
  Hypothesis RLO : r_lo rstk <= lo.
  Hypothesis RHI : SP <= r_hi rstk.
  Hypothesis RRL : ATOP <= r_rlo rstk.
  Hypothesis RRS : rrng RNG rstk.
  Hypothesis WSK : rng RNG lo (al_top L - lo).
  Hypothesis WIM : rng_aimg RNG.
  (* [comment removed for export] *)
  Hypothesis SLOW : w4_slow_goal AI L RNG st LB ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc m0 DST dcap SS DT mtl tl lo src cbs.
  Hypothesis FAP : fast_args_stmtA.

  Notation DW := [(lo, SP); (DST, DST + dcap)].
  Notation POST := (huf_dec_postA AI L RNG ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB DST dcap lo m0).
  Notation FRS := [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

  Ltac c8ifyF H := lazymatch type of H with rw_cells _ ?m ?A ?cs =>
    let rec go pre l := lazymatch l with
       | CB 8 ?b :: ?post => apply (w4_cb8_c8 m A pre post b) in H; cbn [app] in H
       | ?c :: ?l' => go constr:(pre ++ [c]) l'
       | [] => fail end in
    go constr:(@nil cell) cs end.
  Ltac absj H := repeat match type of H with context [le_bytes_to_word ?b] =>
    let w := fresh "wj" in set (w := le_bytes_to_word b) in H; clearbody w end.
  Ltac carveF n ST NEW := carve_frame n ST; lazymatch goal with H : rw_cells _ _ _ [CB _ _] |- _ => rename H into NEW end.
  Ltac ztoF pc := repeat (lazymatch goal with |- evtF _ _ _ (MS _ _ (Z_to_bv 64 pc) _ _ _ _) => fail | _ => zstep end).

  Lemma w4e_sp : 0x10007fff8000 <= SPF /\ SP <= 2^47 /\ ATOP + 4096 <= lo /\ lo + 8192 <= SP.
Proof using AH LOA LOS SPT.
ltac2:(KReplay.run1 (kr_t_AF_huf_w4e ()) ["CANSEC1"; "W4E"] "p;=g029Ql=0Tp,2rcp,2AIp,1Lp,3RNGp,2stp,2LBp,2spp,2m0p,2lop,2AHp,3LOAp,3LOSp,3SPTM=0o"). Qed.

  (* [comment removed for export] *)
  Lemma w4e_blocks : AIMG_HI <= DT /\ DT + DTL <= ATOP /\ DT mod 16 = 0 /\ DT + 4 + zlen cbs <= DT + DTL
                     /\ (dcap = 0 \/ (AIMG_HI <= DST /\ DST + dcap <= ATOP))
